def sayfala(toplam, sayfa, boyut):
    son = (toplam + boyut - 1) // boyut
    baslangic = (sayfa - 1) * boyut
    adet = max(0, min(boyut, toplam - baslangic))
    return {
        "sayfa": sayfa,
        "adet": adet,
        "toplam_sayfa": son,
        "sonraki": sayfa + 1 if sayfa < son else None,
    }


for s in (1, 4, 5):
    c = sayfala(toplam=47, sayfa=s, boyut=12)
    print(c["sayfa"], c["adet"], c["toplam_sayfa"], c["sonraki"])

def ayristir(s):
    return tuple(int(p) for p in s.split("."))


def yukselt(surum, tur):
    buyuk, kucuk, yama = ayristir(surum)
    if tur == "kirici":
        return f"{buyuk + 1}.0.0"
    if tur == "ozellik":
        return f"{buyuk}.{kucuk + 1}.0"
    return f"{buyuk}.{kucuk}.{yama + 1}"


def uyumlu_mu(istemci, sunucu):
    i = ayristir(istemci)
    s = ayristir(sunucu)
    return i[0] == s[0] and s[1:] >= i[1:]


s = "1.4.9"
for tur in ["yama", "yama", "ozellik", "yama", "ozellik", "kirici", "yama"]:
    s = yukselt(s, tur)
    print(tur, s)

print(uyumlu_mu("2.1.0", s))
print(uyumlu_mu("2.0.0", "2.3.1"), uyumlu_mu("2.4.0", "2.3.1"))
